//! The embedded type trees (generated by `scripts/dev/gen_typetrees.py`).
//!
//! * `typetrees/engine.json`: engine classes by class ID (from UnityPy's TPK
//!   database for Unity 2022.3.60f1).
//! * `typetrees/scripts.json`: MonoBehaviour classes by assembly and full
//!   name, fields after the MonoBehaviour header only.

use std::collections::HashMap;
use std::sync::{Arc, OnceLock};

use crate::typetree::{RawNode, RefTypes, TypeTree, raw_nodes_from_json};
use crate::{Error, Result};

const ENGINE_JSON: &str = include_str!("../typetrees/engine.json");
const SCRIPTS_JSON: &str = include_str!("../typetrees/scripts.json");

/// Class ID of MonoBehaviour.
pub const MONO_BEHAVIOUR: i32 = 114;

/// Identifies a script class: assembly without `.dll`, namespace, class name.
#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct ScriptKey {
    /// e.g. `Assembly-CSharp`.
    pub assembly: String,
    /// May be empty.
    pub namespace: String,
    /// Class name.
    pub class: String,
}

impl ScriptKey {
    /// Builds a key, normalising a trailing `.dll` on the assembly.
    pub fn new(assembly: &str, namespace: &str, class: &str) -> Self {
        ScriptKey {
            assembly: assembly.trim_end_matches(".dll").to_owned(),
            namespace: namespace.to_owned(),
            class: class.to_owned(),
        }
    }

    /// `Namespace.Class` or `Class`.
    pub fn full_name(&self) -> String {
        if self.namespace.is_empty() {
            self.class.clone()
        } else {
            format!("{}.{}", self.namespace, self.class)
        }
    }
}

/// All embedded type trees, compiled on first use.
pub struct Registry {
    engine: HashMap<i32, Arc<TypeTree>>,
    engine_names: HashMap<String, i32>,
    scripts: HashMap<ScriptKey, Arc<TypeTree>>,
    /// Plain serializable classes used as `[SerializeReference]` payloads.
    ref_types: HashMap<ScriptKey, Arc<TypeTree>>,
    /// The MonoBehaviour header (`m_GameObject` .. `m_Name`) alone.
    mono_header: Arc<TypeTree>,
}

impl Registry {
    /// The process-wide registry of embedded trees.
    pub fn get() -> &'static Registry {
        static R: OnceLock<Registry> = OnceLock::new();
        R.get_or_init(|| Registry::parse(ENGINE_JSON, SCRIPTS_JSON).expect("embedded type trees"))
    }

    /// Parses registry JSON (engine + scripts files).
    pub fn parse(engine_json: &str, scripts_json: &str) -> Result<Registry> {
        let e: serde_json::Value = serde_json::from_str(engine_json)?;
        let mut engine = HashMap::new();
        let mut engine_names = HashMap::new();
        let mut mono_raw = None;
        for c in e["classes"].as_array().into_iter().flatten() {
            let id = c["id"].as_i64().unwrap_or(-1) as i32;
            let raw = raw_nodes_from_json(&c["nodes"])?;
            if id == MONO_BEHAVIOUR {
                mono_raw = Some(raw.clone());
            }
            engine_names.insert(c["name"].as_str().unwrap_or("").to_owned(), id);
            engine.insert(id, Arc::new(TypeTree::new(raw)?));
        }
        let mono_raw =
            mono_raw.ok_or_else(|| Error::Format("no MonoBehaviour engine tree".into()))?;
        let s: serde_json::Value = serde_json::from_str(scripts_json)?;
        let mut scripts = HashMap::new();
        let mut ref_types = HashMap::new();
        for c in s["ref_types"].as_array().into_iter().flatten() {
            let key = ScriptKey::new(
                c["assembly"].as_str().unwrap_or(""),
                c["namespace"].as_str().unwrap_or(""),
                c["class"].as_str().unwrap_or(""),
            );
            let mut raw = vec![RawNode::new(0, &key.class, "Base", -1, 0)];
            raw.extend(raw_nodes_from_json(&c["nodes"])?);
            ref_types.insert(key, Arc::new(TypeTree::new(raw)?));
        }
        for c in s["scripts"].as_array().into_iter().flatten() {
            let key = ScriptKey::new(
                c["assembly"].as_str().unwrap_or(""),
                c["namespace"].as_str().unwrap_or(""),
                c["class"].as_str().unwrap_or(""),
            );
            let fields = raw_nodes_from_json(&c["nodes"])?;
            scripts.insert(
                key.clone(),
                Arc::new(script_tree(&mono_raw, &key.class, fields)?),
            );
        }
        Ok(Registry {
            mono_header: Arc::new(TypeTree::new(mono_raw)?),
            engine,
            engine_names,
            scripts,
            ref_types,
        })
    }

    /// Engine tree for a class ID.
    pub fn engine(&self, class_id: i32) -> Option<&Arc<TypeTree>> {
        self.engine.get(&class_id)
    }

    /// Class ID for an engine class name (e.g. `Transform`).
    pub fn class_id(&self, name: &str) -> Option<i32> {
        self.engine_names.get(name).copied()
    }

    /// Engine class name for a class ID.
    pub fn class_name(&self, class_id: i32) -> Option<&str> {
        self.engine.get(&class_id).map(|t| t.root_type())
    }

    /// Full MonoBehaviour tree (header + fields) for a script class.
    pub fn script(&self, key: &ScriptKey) -> Option<&Arc<TypeTree>> {
        self.scripts.get(key)
    }

    /// All known script classes.
    pub fn script_keys(&self) -> impl Iterator<Item = &ScriptKey> {
        self.scripts.keys()
    }

    /// The bare MonoBehaviour header tree.
    pub fn mono_header(&self) -> &Arc<TypeTree> {
        &self.mono_header
    }
}

impl RefTypes for Registry {
    fn ref_type(&self, assembly: &str, namespace: &str, class: &str) -> Option<&TypeTree> {
        self.ref_types
            .get(&ScriptKey::new(assembly, namespace, class))
            .map(|t| &**t)
    }
}

/// Engine MonoBehaviour header nodes + script field nodes, root renamed.
fn script_tree(header: &[RawNode], class: &str, fields: Vec<RawNode>) -> Result<TypeTree> {
    let mut raw = header.to_vec();
    raw[0].type_name = class.to_owned();
    raw.extend(fields);
    TypeTree::new(raw)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_registry_has_core_classes() {
        let r = Registry::get();
        for (id, name) in [
            (1, "GameObject"),
            (4, "Transform"),
            (28, "Texture2D"),
            (83, "AudioClip"),
        ] {
            assert_eq!(r.class_name(id), Some(name));
            assert_eq!(r.class_id(name), Some(id));
        }
        let header: Vec<_> = r
            .mono_header()
            .raw()
            .iter()
            .map(|n| n.name.as_str())
            .collect();
        assert_eq!(
            &header[..5],
            ["Base", "m_GameObject", "m_FileID", "m_PathID", "m_Enabled"]
        );
        // The engine header aligns after m_Enabled (the generator's does not).
        assert!(r.mono_header().raw()[4].meta & crate::typetree::ALIGN_BYTES != 0);
        assert!(r.script_keys().count() > 0);
    }
}
